  export function preloadAllFrames() {
    const a = new Image(); a.src = heroFuji;
    const b = new Image(); b.src = heroTemple;
    a.onload = () => drawArborFrame(currentFrameIdx);
    b.onload = () => drawArborFrame(currentFrameIdx);
    for (let i = 0; i < TOTAL_FRAMES; i++) frameImages.push(i < TOTAL_FRAMES / 2 ? a : b);
  }

  let __inited=false;
  export function initSite() {
    if (__inited) return; __inited=true;
    preloadAllFrames();
    initArborScroller();
    initCalendarWidget();
    initCursorSpotlight();

    // Load saved language
    const saved = localStorage.getItem('kakehashi_lang');
    if (saved && translations[saved]) {
      setLanguage(saved);
    } else {
      setLanguage('EN');
    }

    // Header & Navbar Scroll State (Smooth transition on scroll past hero)
    window.addEventListener('scroll', () => {
      const header = document.getElementById('siteHeader');
      const intro = document.getElementById('intro');
      if (header && intro) {
        const rect = intro.getBoundingClientRect();
        const total = intro.offsetHeight - window.innerHeight;
        const progress = Math.max(0, -rect.top / total);
        if (progress >= 0.88 || rect.bottom <= window.innerHeight) {
          header.classList.add('scrolled-past-hero');
        } else {
          header.classList.remove('scrolled-past-hero');
        }
      }
      tickArborScroller();
    }, { passive: true });
  }

  // ==========================================================================
  // CURSOR SPOTLIGHT AMBIENT GLOW SYSTEM
  // ==========================================================================

  export function initCursorSpotlight() {
    window.addEventListener('mousemove', (e) => {
      document.documentElement.style.setProperty('--mouse-x', e.clientX + 'px');
      document.documentElement.style.setProperty('--mouse-y', e.clientY + 'px');
    }, { passive: true });
  }

  // ==========================================================================
  // FULL-SCREEN SCROLL TRANSITION ENGINE (158 FRAMES)
  // Dynamic Canvas Cover Scaling (Crisp across Phones, Tablets, Desktops)
  // ==========================================================================

  let arborRAF = null;
  let currentFrameIdx = 0;
  let currentActiveSlide = 1;

  export function initArborScroller() {
    const canvas = document.getElementById('arborCanvas');
    if (!canvas) return;

    resizeArborCanvas();

    window.addEventListener('resize', () => {
      resizeArborCanvas();
      tickArborScroller();
    }, { passive: true });

    window.addEventListener('orientationchange', () => {
      setTimeout(() => {
        resizeArborCanvas();
        tickArborScroller();
      }, 150);
    }, { passive: true });

    if (frameImages[0]) {
      if (frameImages[0].complete) drawArborFrame(0);
      else frameImages[0].onload = () => drawArborFrame(0);
    }

    tickArborScroller();
  }

  export function resizeArborCanvas() {
    const canvas = document.getElementById('arborCanvas');
    if (!canvas) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = window.innerWidth;
    const h = window.innerHeight;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    drawArborFrame(currentFrameIdx);
  }

  export function tickArborScroller() {
    if (arborRAF) cancelAnimationFrame(arborRAF);
    arborRAF = requestAnimationFrame(runArborScroller);
  }

  export function runArborScroller() {
    const section = document.getElementById('intro');
    if (!section) return;

    const rect = section.getBoundingClientRect();
    const total = section.offsetHeight - window.innerHeight;
    const scrolled = -rect.top;
    const progress = Math.max(0, Math.min(1, scrolled / total));

    // Map progress to frame 0..157
    const frameIndex = Math.min(TOTAL_FRAMES - 1, Math.floor(progress * TOTAL_FRAMES));

    if (frameIndex !== currentFrameIdx || progress === 0) {
      currentFrameIdx = frameIndex;
      drawArborFrame(frameIndex);
    }

    // Update Progress Line
    const line = document.getElementById('scrollProgressLine');
    if (line) line.style.width = (progress * 100).toFixed(2) + '%';

    // Update Frame Badge
    const badge = document.getElementById('frameProgressBadge');
    if (badge) badge.textContent = `${String(frameIndex + 1).padStart(3, '0')} / 158`;

    // Slide 1: ACQUIRE (0% - 33%)
    // Slide 2: ARCHITECT (33% - 66%)
    // Slide 3: AWAKEN (66% - 100%)
    let activeSlide = 1;
    if (progress < 0.333) activeSlide = 1;
    else if (progress < 0.666) activeSlide = 2;
    else activeSlide = 3;

    if (activeSlide !== currentActiveSlide) {
      currentActiveSlide = activeSlide;

      ['slide1', 'slide2', 'slide3'].forEach((id, i) => {
        const el = document.getElementById(id);
        if (el) el.classList.toggle('active', i + 1 === activeSlide);
      });

      ['dot1', 'dot2', 'dot3'].forEach((id, i) => {
        const el = document.getElementById(id);
        if (el) el.classList.toggle('active', i + 1 === activeSlide);
      });
    }

    // Fade out explore indicator after scroll starts
    const explore = document.getElementById('exploreIndicator');
    if (explore) {
      explore.classList.toggle('hidden', progress > 0.04);
    }
  }

  // Draw image to canvas using aspect-ratio 'cover' mathematics
  export function drawArborFrame(index) {
    const canvas = document.getElementById('arborCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const img = frameImages[index];

    if (img && img.complete && img.naturalWidth > 0) {
      const cw = canvas.width;
      const ch = canvas.height;
      const imgRatio = img.naturalWidth / img.naturalHeight;
      const canvasRatio = cw / ch;
      let rw, rh, ox, oy;

      if (canvasRatio > imgRatio) {
        rw = cw;
        rh = cw / imgRatio;
        ox = 0;
        oy = (ch - rh) / 2;
      } else {
        rh = ch;
        rw = ch * imgRatio;
        ox = (cw - rw) / 2;
        oy = 0;
      }

      const half = TOTAL_FRAMES / 2;
      const t = (index % half) / half;
      const z = 1.04 + t * 0.14;
      const zw = rw * z, zh = rh * z;
      ctx.clearRect(0, 0, cw, ch);
      ctx.drawImage(img, ox - (zw - rw) / 2, oy - (zh - rh) / 2, zw, zh);
    }
  }


  // ==========================================================================
  // MULTILINGUAL SYSTEM
  // ==========================================================================

  export function setLanguage(lang) {
    if (!translations[lang]) return;
    currentLang = lang;
    localStorage.setItem('kakehashi_lang', lang);

    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (translations[lang][key]) {
        el.textContent = translations[lang][key];
      }
    });

    document.querySelectorAll('.lang-btn').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-lang') === lang);
    });
  }

  // ==========================================================================
  // CALENDAR SCHEDULER ENGINE
  // ==========================================================================

  let currentCalYear = 2026;
  let currentCalMonth = 9; // October (0-indexed)
  let selectedCalDate = 28;
  let selectedServiceType = 'discovery';
  let selectedServiceName = 'Discovery Call';
  let selectedServiceDuration = '30 Min';
  let selectedTimeSlot = '12:30 CET';

  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  export function initCalendarWidget() {
    renderCalendar();
    updateBookingSummary();
  }

  export function renderCalendar() {
    const monthTitle = document.getElementById('calMonthTitle');
    const grid = document.getElementById('calendarGrid');
    if (!monthTitle || !grid) return;

    monthTitle.textContent = `${monthNames[currentCalMonth]} ${currentCalYear}`;
    grid.innerHTML = '';

    const firstDayIndex = new Date(currentCalYear, currentCalMonth, 1).getDay();
    const startDay = (firstDayIndex + 6) % 7;
    const daysInMonth = new Date(currentCalYear, currentCalMonth + 1, 0).getDate();

    for (let i = 0; i < startDay; i++) {
      const empty = document.createElement('div');
      empty.className = 'cal-day-cell empty';
      grid.appendChild(empty);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const cell = document.createElement('button');
      cell.type = 'button';
      cell.className = 'cal-day-cell available';
      cell.textContent = d;

      if (d === selectedCalDate) cell.classList.add('selected');
      cell.onclick = () => selectDate(d);
      grid.appendChild(cell);
    }

    const dateLabel = document.getElementById('slotsDateLabel');
    if (dateLabel) {
      dateLabel.textContent = `${monthNames[currentCalMonth].substring(0,3)} ${selectedCalDate}, ${currentCalYear}`;
    }
  }

  export function prevMonth() {
    currentCalMonth--;
    if (currentCalMonth < 0) {
      currentCalMonth = 11;
      currentCalYear--;
    }
    selectedCalDate = 15;
    renderCalendar();
    updateBookingSummary();
  }

  export function nextMonth() {
    currentCalMonth++;
    if (currentCalMonth > 11) {
      currentCalMonth = 0;
      currentCalYear++;
    }
    selectedCalDate = 15;
    renderCalendar();
    updateBookingSummary();
  }

  export function selectDate(d) {
    selectedCalDate = d;
    document.querySelectorAll('.cal-day-cell').forEach(c => {
      c.classList.remove('selected');
      if (c.textContent == d && !c.classList.contains('empty')) c.classList.add('selected');
    });

    const dateLabel = document.getElementById('slotsDateLabel');
    if (dateLabel) {
      dateLabel.textContent = `${monthNames[currentCalMonth].substring(0,3)} ${selectedCalDate}, ${currentCalYear}`;
    }
    updateBookingSummary();
  }

  export function selectConsultationType(type, btn) {
    selectedServiceType = type;
    document.querySelectorAll('.stype-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');

    if (type === 'discovery') {
      selectedServiceName = 'Discovery Call';
      selectedServiceDuration = '30 Min';
    } else if (type === 'audit') {
      selectedServiceName = 'Listing Review';
      selectedServiceDuration = '45 Min';
    } else {
      selectedServiceName = 'Renovation Scope';
      selectedServiceDuration = '45 Min';
    }
    updateBookingSummary();
  }

  export function selectTimeSlot(slot, btn) {
    selectedTimeSlot = `${slot} CET`;
    document.querySelectorAll('.aslot-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    updateBookingSummary();
  }

  export function updateBookingSummary() {
    const pill = document.getElementById('bookingSummaryPill');
    if (!pill) return;
    pill.innerHTML = `Selected: <strong>${selectedServiceName} (${selectedServiceDuration})</strong> on <strong>${monthNames[currentCalMonth].substring(0,3)} ${selectedCalDate}, ${currentCalYear} at ${selectedTimeSlot}</strong>`;
  }

  export function handleScheduleSubmit(e) {
    e.preventDefault();
    const email = document.getElementById('schedEmail').value;
    document.getElementById('confirmedEmail').textContent = email;

    document.getElementById('schedPickersSplit').style.display = 'none';
    document.getElementById('schedFormBox').style.display = 'none';
    document.getElementById('schedSuccessBox').style.display = 'block';
  }

  export function resetScheduler() {
    document.getElementById('schedPickersSplit').style.display = 'grid';
    document.getElementById('schedFormBox').style.display = 'block';
    document.getElementById('schedSuccessBox').style.display = 'none';
  }

  export function downloadIcsFile() {
    const ics = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//Maison Kakehashi//EN',
      'BEGIN:VEVENT',
      `SUMMARY:Maison Kakehashi Consultation - ${selectedServiceName}`,
      'DESCRIPTION:Google Meet Link: https://meet.google.com/mkh-jpan-cal',
      'LOCATION:Google Meet Video Call',
      'STATUS:CONFIRMED',
      'END:VEVENT',
      'END:VCALENDAR'
    ].join('\r\n');

    const blob = new Blob([ics], { type: 'text/calendar;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'Maison_Kakehashi_Consultation.ics';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  // FAQ Accordion
  export function toggleFaq(item) {
    const isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-arbor-item').forEach(el => {
      el.classList.remove('open');
      const ans = el.querySelector('.faq-arbor-answer');
      if (ans) ans.style.maxHeight = null;
    });

    if (!isOpen) {
      item.classList.add('open');
      const ans = item.querySelector('.faq-arbor-answer');
      if (ans) ans.style.maxHeight = ans.scrollHeight + 30 + 'px';
    }
  }

  // Card Flip
  export function toggleCardFlip() {
    const inner = document.getElementById('cardInner');
    if (inner) inner.classList.toggle('flipped');
  }

  // Mobile Menu with overlay & scroll lock
  export function openMobileMenu() {
    const drawer = document.getElementById('mobileDrawer');
    const overlay = document.getElementById('mobileDrawerOverlay');
    if (drawer) drawer.classList.add('open');
    if (overlay) overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  }

  export function closeMobileMenu() {
    const drawer = document.getElementById('mobileDrawer');
    const overlay = document.getElementById('mobileDrawerOverlay');
    if (drawer) drawer.classList.remove('open');
    if (overlay) overlay.classList.remove('open');
    document.body.style.overflow = '';
  }


  // Lifestyle Modal
  export function openLifestyleModal(cardNum) {
    const t = translations[currentLang];
    const modal = document.getElementById('lifestyleModal');
    const title = document.getElementById('modalTitle');
    const desc = document.getElementById('modalDesc');
    const details = document.getElementById('modalDetails');

    if (title) title.textContent = t[`card${cardNum}_title`];
    if (desc) desc.textContent = t[`card${cardNum}_desc`];
    if (details) details.textContent = t[`card${cardNum}_modal_details`];

    if (modal) modal.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  export function closeLifestyleModal(e) {
    if (e.target.id === 'lifestyleModal') closeLifestyleModalDirect();
  }

  export function closeLifestyleModalDirect() {
    const modal = document.getElementById('lifestyleModal');
    if (modal) modal.classList.remove('active');
    document.body.style.overflow = '';
  }

